/**
 * Calibration regression fixtures — substrate eval.
 *
 * Each fixture is a (propertyData, assumptions, userContext, expected)
 * tuple. The eval runs the tool chain (compute_analysis → score_deal)
 * on the inputs, then asserts:
 *
 *   - DecisionEvent.dealQuality === expected.dealQuality (zero tolerance)
 *   - AnalysisEvent + DecisionEvent both written
 *
 * Per /docs/PRODUCT_2.0_EVALS.md §3.4 — the regression set's `expected`
 * values are generated by running the existing engine on `inputs` at
 * fixture-creation time. If the engine intentionally changes, fixtures
 * are regenerated and `lastValidated` is bumped.
 *
 * Wave-1 scaffolding: 3 fixtures (one per scoring band). Volume scales
 * post-wave-1 when the founder-historical backfill ships.
 *
 * INITIAL CALIBRATION ANCHOR
 * --------------------------
 *
 * The dealQuality values below were obtained by running each fixture
 * through the legacy engine via the smoke-test harness on 2026-05-13.
 * They represent the V3.0 engine's current calibration. Updating them
 * is a deliberate change — see eval-substrate.ts header comment for
 * the update procedure.
 */

import type { SFRData, BRRRRStrategyData } from '../../../types/propertyTypes';
import type { AnalysisAssumptions } from '../../../analysis/BasePropertyAnalyzer';
import { assertCanonicalStrategy, type CanonicalStrategy } from '../../../domain/strategy';

/**
 * Calibration fixture property data.
 *
 * Base shape is SFRData. The two engine-routing fields the
 * InvestmentDecisionEngine reads via `(propertyData as any)` —
 * `investmentStrategy` and the BRRRR-specific `brrrr` block — are
 * declared here explicitly so BRRRR fixtures are typed, not casted.
 *
 *   - investmentStrategy: 'brrrr' routes to generateBRRRRDecision
 *     (which recomputes its own analysis via BRRRRAnalyzer).
 *   - 'buy_hold' (or absent) routes to the standard engine path.
 *   - `brrrr` carries rehabBudget / afterRepairValue / refinanceLTV /
 *     etc. — required when investmentStrategy is 'brrrr'.
 */
export type FixturePropertyData = SFRData & {
  // Issue #243 (2026-07-12, iteration-2): widen to the full canonical
  // enum for typechecking parity with dealMetrics + the resolver
  // input schema. House-hack fixtures aren't run through the resolver
  // yet (analyzer routing → Issue #257), but the type parity here
  // prevents drift once that ships.
  investmentStrategy?: CanonicalStrategy;
  brrrr?: BRRRRStrategyData;
};

export interface CalibrationFixture {
  /** Human-readable name. Surfaces in PASS/FAIL output. */
  name: string;
  /** Engine version this fixture was calibrated against. */
  engineVersion: string;
  /** YYYY-MM-DD when the expected values were last regenerated. */
  lastValidated: string;
  /** Inputs to the tool chain. */
  inputs: {
    propertyData: FixturePropertyData;
    assumptions: AnalysisAssumptions;
    userContext: {
      riskTolerance: 'conservative' | 'moderate' | 'aggressive';
      availableCash?: number;
    };
  };
  /** What the substrate-persisted dealQuality MUST equal. */
  expected: {
    dealQuality: number;
    qualityLabel:
      | 'Above professional standards'
      | 'Meets professional standards'
      | 'Requires optimization'
      | 'Below professional standards';
  };
}

const standardAssumptions: AnalysisAssumptions = {
  projectionYears: 10,
  annualRentIncrease: 3,
  annualExpenseIncrease: 2.5,
  annualPropertyValueIncrease: 3.5,
  sellingCosts: 6,
  vacancyRate: 5,
};

